  launcher.addEventListener('click',restore);root().append(launcher);
  document.addEventListener('fullscreenchange',()=>{(document.fullscreenElement||root()).append(launcher)});
  root().setAttribute('data-ha-mobile-state','loading');timer=setInterval(update,250);
